import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"7.2 变压器的结构与分类","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-2-bian-ya-qi-de-jie-gou-yu-fen-lei.md","filePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-2-bian-ya-qi-de-jie-gou-yu-fen-lei.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-2-bian-ya-qi-de-jie-gou-yu-fen-lei.md"};function i(n,t,s,d,h,g){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_7-2-变压器的结构与分类" tabindex="-1">7.2 变压器的结构与分类 <a class="header-anchor" href="#_7-2-变压器的结构与分类" aria-label="Permalink to &quot;7.2 变压器的结构与分类&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>7.1 讲了原理,这一节看&quot;实物&quot;——变压器由什么做成、分成哪些类型,重点是<strong>油浸式与干式</strong>的区别,以及三相变压器与安全隔离变压器的位置。</p><h2 id="一、变压器的基本结构" tabindex="-1">一、变压器的基本结构 <a class="header-anchor" href="#一、变压器的基本结构" aria-label="Permalink to &quot;一、变压器的基本结构&quot;">​</a></h2><p>变压器的主要组成部分:</p><table tabindex="0"><thead><tr><th>部件</th><th>材料/构成</th><th>作用</th></tr></thead><tbody><tr><td><strong>铁芯</strong></td><td>硅钢片<strong>叠压</strong>而成</td><td>导磁,把交变磁通集中,提高效率</td></tr><tr><td><strong>绕组(线圈)</strong></td><td>绝缘铜(铝)线绕成</td><td>一次绕组接电源、二次绕组接负载</td></tr><tr><td><strong>绝缘</strong></td><td>绝缘纸、绝缘漆、绝缘油</td><td>绕组之间、绕组与铁芯之间绝缘</td></tr><tr><td><strong>外壳/附件</strong></td><td>油箱、接线端子、散热器等</td><td>保护与散热</td></tr></tbody></table><blockquote><p>💡 铁芯为什么用<strong>硅钢片叠压</strong>而不是整块钢?因为整块铁芯在交变磁通下会产生很大的涡流(发热浪费电);叠成薄片能<strong>减小涡流损耗</strong>,提高效率——判断题常考。</p></blockquote><h2 id="二、变压器的分类" tabindex="-1">二、变压器的分类 <a class="header-anchor" href="#二、变压器的分类" aria-label="Permalink to &quot;二、变压器的分类&quot;">​</a></h2><h3 id="_1-按相数分" tabindex="-1">1. 按相数分 <a class="header-anchor" href="#_1-按相数分" aria-label="Permalink to &quot;1. 按相数分&quot;">​</a></h3><ul><li><strong>单相变压器</strong>:用于单相负荷(小容量);</li><li><strong>三相变压器</strong>:用于三相供电(配电变压器多为三相)。</li></ul><h3 id="_2-按冷却方式分-重点" tabindex="-1">2. 按冷却方式分(重点) <a class="header-anchor" href="#_2-按冷却方式分-重点" aria-label="Permalink to &quot;2. 按冷却方式分(重点)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>冷却方式</th><th>特点</th></tr></thead><tbody><tr><td><strong>油浸式变压器</strong></td><td>变压器油循环散热</td><td>散热好、容量大,需油箱、防渗漏,用于户外/大容量</td></tr><tr><td><strong>干式变压器</strong></td><td>空气(自然)冷却</td><td>无油、无渗漏风险、安全,用于室内、对防火要求高的场所</td></tr></tbody></table><blockquote><p>💡 记忆:油浸式=油多散热好(大容量户外);干式=不用油(室内安全)。</p></blockquote><h3 id="_3-按用途分" tabindex="-1">3. 按用途分 <a class="header-anchor" href="#_3-按用途分" aria-label="Permalink to &quot;3. 按用途分&quot;">​</a></h3><ul><li><strong>电力变压器</strong>:升压、降压,用于电网(如 10 kV/0.4 kV 配电变压器);</li><li><strong>隔离变压器</strong>:电压不变,起电气隔离作用;</li><li><strong>安全隔离变压器</strong>:提供安全电压(7.4 节详讲);</li><li><strong>仪表用互感器</strong>:电压互感器、电流互感器(用于测量)。</li></ul><h2 id="三、三相变压器的联接" tabindex="-1">三、三相变压器的联接 <a class="header-anchor" href="#三、三相变压器的联接" aria-label="Permalink to &quot;三、三相变压器的联接&quot;">​</a></h2><p>三相变压器三个绕组按 <strong>星形(Y)或三角形(△)</strong> 联接(对应 2.5 节三相知识),把三相电压按比例转换,输出三相电。</p><h2 id="四、油浸式变压器的主要附件" tabindex="-1">四、油浸式变压器的主要附件 <a class="header-anchor" href="#四、油浸式变压器的主要附件" aria-label="Permalink to &quot;四、油浸式变压器的主要附件&quot;">​</a></h2><ul><li><strong>油箱</strong>:盛装变压器油;</li><li><strong>绝缘油</strong>:既绝缘又散热;</li><li><strong>散热器/冷却管</strong>:帮助散热;</li><li><strong>防爆管(安全气道)</strong>、<strong>呼吸器(油枕)</strong> 等保护附件。</li></ul><blockquote><p>⚠️ 油浸式变压器运行中要<strong>注意渗油、油位</strong>,油位过低影响散热和绝缘。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 铁芯用<strong>硅钢片叠压</strong>,目的是<strong>减小涡流损耗</strong>。</li><li>✅ 油浸式(散热好、容量大)vs 干式(无油、室内安全)。</li><li>✅ 配电用<strong>三相变压器</strong>;安全电压用<strong>安全隔离变压器</strong>。</li><li>⚠️ 易混点:油浸式≠干式,一个靠油散热一个靠空气散热。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>变压器由铁芯(硅钢片)+ 一次/二次绕组构成。</li><li>冷却方式分油浸式和干式;按相数分单相、三相。</li><li>硅钢片叠压是为了减小涡流损耗。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)变压器铁芯采用硅钢片叠压而成,是为了减小涡流损耗。( )</li><li>(单选)大容量户外变压器一般选用()。 A. 干式　B. 油浸式　C. 风冷　D. 自然冷却</li><li>(判断)干式变压器没有变压器油,渗漏风险小,适用于室内场所。( )</li><li>(单选)为三相负荷供电的配电变压器,一般是()变压器。 A. 单相　B. 三相　C. 自耦　D. 仪表用</li><li>(判断)油浸式变压器运行中应注意油位和渗油情况。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。硅钢片叠压减小涡流损耗。</li><li><strong>B</strong>。油浸式散热好,用于大容量户外。</li><li><strong>√</strong>。干式无油,适用于室内防火要求高的场所。</li><li><strong>B</strong>。三相供电用三相变压器。</li><li><strong>√</strong>。油位、渗油是油浸式的运行检查重点。</li></ol></details>',27)])])}const b=a(e,[["render",i]]);export{u as __pageData,b as default};
